      <div class="month-title" id="monthTitle">أكتوبر ٢٠٢٦</div>
      <button class="nav-arrow" id="nextMonth">▶</button>
    </div>

    <!-- Calendar -->
    <div class="calendar">
      <div class="weekdays">
        <div>س</div>
        <div>أ</div>
        <div>إ</div>
        <div>ث</div>
        <div>ج</div>
        <div>ح</div>
        <div>خ</div>
      </div>
      <div class="days" id="calendarDays"></div>
    </div>

    <!-- Time Slots -->
    <div class="time-slots">
      <h2>اختر وقتًا</h2>
      <div class="slots-container" id="timeSlots">
        <div class="slot">٩:٠٠ ص</div>
        <div class="slot">٩:٣٠ ص</div>
        <div class="slot">١٠:٠٠ ص</div>
        <div class="slot">١٠:٣٠ ص</div>
        <div class="slot">١١:٠٠ ص</div>
        <div class="slot">١١:٣٠ ص</div>
        <div class="slot">١٢:٠٠ م</div>
      </div>
    </div>

    <!-- Doctor Info -->
    <div class="doctor-info">
      <img src="https://via.placeholder.com/56" alt="د. فاطمة الزهراء" />
      <div>
        <div class="name">د. فاطمة الزهراء</div>
        <div class="title">أخصائية أمراض القلب</div>
      </div>
    </div>

    <!-- Confirm Button -->
    <button class="confirm-button">تأكيد الحجز</button>
  </div>

