      </div>
    </div>

    <!-- Confirm Button -->
    <button class="confirm-button">تأكيد الحجز</button>
  </div>

  <script>
    const monthNames = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];

    const today = new Date();
    let currentMonth = today.getMonth();
    let currentYear = today.getFullYear();

    const monthTitle = document.getElementById("monthTitle");
    const calendarDays = document.getElementById("calendarDays");
    const prevMonthBtn = document.getElementById("prevMonth");
    const nextMonthBtn = document.getElementById("nextMonth");

    function renderCalendar() {
      const firstDay = new Date(currentYear, currentMonth, 1).getDay();
      const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

      // Adjust for Saturday start (Qatar weekend is Fri-Sat)
      const startDayOffset = (firstDay === 0) ? 1 : firstDay; // Shift so Saturday is first

      monthTitle.textContent = `${monthNames[currentMonth]} ${currentYear}`;
      calendarDays.innerHTML = "";

      // Fill previous month's remaining days
      const prevDays = (startDayOffset === 6) ? 0 : startDayOffset;
      for (let i = 0; i < prevDays; i++) {
        const dayDiv = document.createElement("div");
        dayDiv.classList.add("day", "other-month");
        dayDiv.textContent = "";
        calendarDays.appendChild(dayDiv);
      }

      // Fill current month's days
      for (let d = 1; d <= daysInMonth; d++) {
        const dayDiv = document.createElement("div");
        dayDiv.classList.add("day");
        dayDiv.textContent = d;

        if (
          d === today.getDate() &&
          currentMonth === today.getMonth() &&
          currentYear === today.getFullYear()
        ) {
          dayDiv.classList.add("today");
        }

        dayDiv.addEventListener("click", () => {
          document.querySelectorAll(".day").forEach(el => el.classList.remove("selected"));
          dayDiv.classList.add("selected");
        });

        calendarDays.appendChild(dayDiv);
      }
    }

    prevMonthBtn.addEventListener("click", () => {
      currentMonth--;
      if (currentMonth < 0) {
        currentMonth = 11;
        currentYear--;
      }
      renderCalendar();
    });

    nextMonthBtn.addEventListener("click", () => {
      currentMonth++;
      if (currentMonth > 11) {
        currentMonth = 0;
        currentYear++;
      }
      renderCalendar();
    });

    // Time slot selection
    document.querySelectorAll(".slot").forEach(slot => {
      slot.addEventListener("click", () => {
        document.querySelectorAll(".slot").forEach(el => el.classList.remove("selected"));
        slot.classList.add("selected");
      });
    });

    renderCalendar();
  </script>
</body>
</html>
